// One item per attachment that could be an invoice; the API's own byte check makes the final call.
// Accept by MIME type or file extension (some mail clients send PDFs as application/octet-stream),
// and skip small images, which are signature logos and inline pictures rather than documents.
const TYPES = new Set(['application/pdf', 'image/jpeg', 'image/png']);
const EXTENSIONS = /\.(pdf|jpe?g|png)$/i;
const MIN_IMAGE_BYTES = 15000;
const UNITS = { B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 };
const bytes = (size) => {
  const m = /^([\d.]+)\s*([kKMG]?B)$/.exec(String(size ?? '').trim());
  return m ? Number(m[1]) * UNITS[m[2]] : NaN;
};
// Never take in mail if the intake address is missing: the Gmail query would then match every email.
if (!String($env.GMAIL_INTAKE_ADDRESS ?? '').includes('@')) return [];
const out = [];
for (const item of $input.all()) {
  for (const [key, bin] of Object.entries(item.binary ?? {})) {
    if (!key.startsWith('attachment_')) continue;
    const name = bin.fileName ?? '';
    if (!TYPES.has(bin.mimeType) && !EXTENSIONS.test(name)) continue;
    const isImage = (bin.mimeType ?? '').startsWith('image/') || /\.(jpe?g|png)$/i.test(name);
    if (isImage && bytes(bin.fileSize) < MIN_IMAGE_BYTES) continue;
    out.push({
      json: { messageId: item.json.id, subject: item.json.subject, fileName: name },
      binary: { data: bin },
    });
  }
}
return out;
